/// Return the lowest index `i` with `arr[i] == x` in a non-decreasingly
/// sorted slice `arr`, or `-1` when `x` does not occur in `arr`.
pub fn first_in_sorted(arr: &[i64], x: i64) -> i64 {
    // Binary search for the lower bound (first index with arr[i] >= x).
    let mut lo: i64 = 0;
    let mut hi: i64 = arr.len() as i64;
    while lo < hi {
        let mid = lo + (hi - lo) / 2;
        if arr[mid as usize] < x {
            lo = mid + 1;
        } else {
            hi = mid;
        }
    }
    if lo < arr.len() as i64 && arr[lo as usize] == x {
        lo
    } else {
        -1
    }
}

#[cfg(test)]
mod tests {
    use super::first_in_sorted;
    use proptest::prelude::*;

    #[test]
    fn examples() {
        assert_eq!(first_in_sorted(&[3, 4, 5, 5, 5, 5, 6], 5), 2);
        assert_eq!(first_in_sorted(&[1, 2], 7), -1);
    }

    #[test]
    fn edge_cases() {
        assert_eq!(first_in_sorted(&[], 0), -1);
        assert_eq!(first_in_sorted(&[], i64::MIN), -1);
        assert_eq!(first_in_sorted(&[], i64::MAX), -1);

        let single = [42_i64];
        assert_eq!(first_in_sorted(&single, 42), 0);
        assert_eq!(first_in_sorted(&single, 41), -1);
        assert_eq!(first_in_sorted(&single, 43), -1);

        assert_eq!(first_in_sorted(&[1, 2, 3], 1), 0);
        assert_eq!(first_in_sorted(&[1, 2, 3], 3), 2);
        assert_eq!(first_in_sorted(&[1, 2, 3], 0), -1);
        assert_eq!(first_in_sorted(&[1, 2, 3], 4), -1);
        assert_eq!(first_in_sorted(&[1, 2, 3], 2), 1);

        let all_same = [7_i64; 10];
        assert_eq!(first_in_sorted(&all_same, 7), 0);
        assert_eq!(first_in_sorted(&all_same, 8), -1);
        assert_eq!(first_in_sorted(&all_same, 6), -1);

        assert_eq!(first_in_sorted(&[i64::MIN, i64::MIN, i64::MAX], i64::MIN), 0);
        assert_eq!(first_in_sorted(&[i64::MIN, i64::MAX, i64::MAX], i64::MAX), 1);
    }

    fn reference(arr: &[i64], x: i64) -> i64 {
        arr.iter().position(|&v| v == x).map(|i| i as i64).unwrap_or(-1)
    }

    proptest! {
        #![proptest_config(ProptestConfig::with_cases(2000))]

        #[test]
        fn matches_linear_scan(x in any::<i64>(), arr in prop::collection::vec(any::<i64>(), 0..200)) {
            let mut sorted: Vec<i64> = arr;
            sorted.sort();
            prop_assert_eq!(first_in_sorted(&sorted, x), reference(&sorted, x));
        }

        #[test]
        fn matches_linear_scan_small_values(x in -50_i64..=50_i64, arr in prop::collection::vec(any::<i64>(), 0..300)) {
            let mut sorted: Vec<i64> = arr;
            sorted.sort();
            prop_assert_eq!(first_in_sorted(&sorted, x), reference(&sorted, x));
        }
    }
}

//! Find the k-th smallest element of a slice (0-indexed, duplicates counted).

/// Returns the element at index `k` of `arr` sorted in non-decreasing order,
/// i.e. the k-th smallest element counting repeated values as often as they occur.
///
/// # Preconditions
/// - `arr` is non-empty
/// - `k < arr.len()`
pub fn kth_smallest(arr: &[i64], k: usize) -> i64 {
    let mut v = arr.to_vec();
    v.sort_unstable();
    v[k]
}

#[cfg(test)]
mod tests {
    use super::kth_smallest;
    use proptest::prelude::*;

    /// Independent O(n) expected-value selection (deterministic middle pivot,
    /// Lomuto partition) used as an oracle for the property tests.
    fn quickselect(arr: &[i64], k: usize) -> i64 {
        let mut v = arr.to_vec();
        let mut lo = 0usize;
        let mut hi = v.len();
        while lo < hi {
            // Move middle element to the end as pivot.
            let pivot_pos = (lo + hi) / 2;
            v.swap(pivot_pos, hi - 1);
            let pivot = v[hi - 1];
            // Elements <= pivot end up in [lo, i).
            let mut i = lo;
            for j in lo..hi - 1 {
                if v[j] <= pivot {
                    v.swap(i, j);
                    i += 1;
                }
            }
            v.swap(i, hi - 1);
            if i == k {
                return v[i];
            } else if i < k {
                lo = i + 1;
            } else {
                hi = i;
            }
        }
        v[lo]
    }

    #[test]
    fn task_examples() {
        let a = [7i64, 1, 7, 3];
        assert_eq!(kth_smallest(&a, 0), 1);
        assert_eq!(kth_smallest(&a, 1), 3);
        assert_eq!(kth_smallest(&a, 2), 7);
        assert_eq!(kth_smallest(&a, 3), 7);
    }

    #[test]
    fn single_element() {
        assert_eq!(kth_smallest(&[42], 0), 42);
    }

    #[test]
    fn all_duplicates() {
        let a = [5i64; 7];
        for k in 0..7 {
            assert_eq!(kth_smallest(&a, k), 5);
        }
    }

    #[test]
    fn already_sorted_and_reversed() {
        let asc = [1i64, 2, 3, 4, 5, 6];
        let desc: Vec<i64> = asc.iter().rev().copied().collect();
        for k in 0..asc.len() {
            assert_eq!(kth_smallest(&asc, k), 1 + k as i64);
            assert_eq!(kth_smallest(&desc, k), 1 + k as i64);
        }
    }

    #[test]
    fn negatives_and_extremes() {
        let a = [i64::MAX, i64::MIN, 0, -1, i64::MIN, i64::MAX];
        assert_eq!(kth_smallest(&a, 0), i64::MIN);
        assert_eq!(kth_smallest(&a, 1), i64::MIN);
        assert_eq!(kth_smallest(&a, 2), -1);
        assert_eq!(kth_smallest(&a, 3), 0);
        assert_eq!(kth_smallest(&a, 4), i64::MAX);
        assert_eq!(kth_smallest(&a, 5), i64::MAX);
    }

    #[test]
    fn largest_allowed_length() {
        // 300 distinct values (0..300), scrambled deterministically.
        let mut v: Vec<i64> = (0..300i64).rev().collect();
        let len = v.len();
        for i in 0..len {
            let j = (i * 97 + 13) % len;
            v.swap(i, j);
        }
        let expected: Vec<i64> = (0..300).collect();
        for k in 0..300 {
            assert_eq!(kth_smallest(&v, k), expected[k]);
        }
    }

    proptest! {
        #[test]
        fn matches_quickselect_on_random_arrays(
            arr in prop::collection::vec(any::<i64>(), 1..=300),
            kb in any::<usize>(),
        ) {
            let k = kb % arr.len();
            prop_assert_eq!(kth_smallest(&arr, k), quickselect(&arr, k));
        }

        #[test]
        fn duplicates_heavy_random_arrays(
            arr in prop::collection::vec((0..5).prop_map(|x| x as i64 * 2 - 4), 1..=300),
            kb in any::<usize>(),
        ) {
            let k = kb % arr.len();
            prop_assert_eq!(kth_smallest(&arr, k), quickselect(&arr, k));
            // Also check a spread of k values.
            for k in [0usize, arr.len() / 2, arr.len() - 1].iter().copied() {
                prop_assert_eq!(kth_smallest(&arr, k), quickselect(&arr, k));
            }
        }
    }
}

//! Longest strictly increasing subsequence (LIS) length.

/// Returns the length of the longest strictly increasing subsequence of `arr`
/// (elements in their original order, not necessarily adjacent, each greater
/// than the one before).
///
/// Uses the patience-sorting approach: `tails[k]` is the smallest possible
/// tail value of any strictly increasing subsequence of length `k + 1` seen
/// so far. For each element `x`, we place it at the first position whose tail
/// is `>= x` (`partition_point(|&t| t < x)`), which either extends the
/// longest subsequence or lowers a tail. Strictness comes from keeping
/// positions with `t < x` unchanged.
///
/// # Examples
/// ```
/// use solution::lis_length;
///
/// assert_eq!(lis_length(&[4, 1, 5, 3, 7, 6, 2]), 3);
/// assert_eq!(lis_length(&[2, 2, 2]), 1);
/// assert_eq!(lis_length(&[]), 0);
/// ```
pub fn lis_length(arr: &[i64]) -> usize {
    let mut tails: Vec<i64> = Vec::new();
    for &x in arr {
        match tails.partition_point(|&t| t < x) {
            pos if pos == tails.len() => tails.push(x),
            pos => tails[pos] = x,
        }
    }
    tails.len()
}

#[cfg(test)]
mod tests {
    use super::lis_length;
    use proptest::prelude::*;

    /// Reference 1: O(2^n) over all subsets, then O(k^2) DP per subset.
    /// Only for small inputs.
    fn brute_force(arr: &[i64]) -> usize {
        let n = arr.len();
        if n == 0 {
            return 0;
        }
        let mut best = 0usize;
        for mask in 0..(1usize << n) {
            let selected: Vec<i64> = (0..n)
                .filter(|&i| (mask >> i) & 1 == 1)
                .map(|i| arr[i])
                .collect();
            let k = selected.len();
            if k == 0 {
                continue;
            }
            let mut dp = vec![1usize; k];
            for i in 0..k {
                for j in 0..i {
                    if selected[j] < selected[i] {
                        dp[i] = dp[i].max(dp[j] + 1);
                    }
                }
            }
            best = best.max(*dp.iter().max().unwrap());
        }
        best
    }

    /// Reference 2: classic O(n^2) DP, independent of the patience-sorting
    /// implementation. Works for the full input size (n <= 100).
    fn dp_reference(arr: &[i64]) -> usize {
        let n = arr.len();
        if n == 0 {
            return 0;
        }
        let mut dp = vec![1usize; n];
        let mut best = 1usize;
        for i in 0..n {
            for j in 0..i {
                if arr[j] < arr[i] {
                    dp[i] = dp[i].max(dp[j] + 1);
                }
            }
            best = best.max(dp[i]);
        }
        best
    }

    #[test]
    fn given_examples() {
        assert_eq!(lis_length(&[4, 1, 5, 3, 7, 6, 2]), 3);
        assert_eq!(lis_length(&[2, 2, 2]), 1);
        assert_eq!(lis_length(&[]), 0);
    }

    #[test]
    fn edge_cases() {
        assert_eq!(lis_length(&[5]), 1);
        assert_eq!(lis_length(&[1, 2, 3, 4, 5]), 5);
        assert_eq!(lis_length(&[5, 4, 3, 2, 1]), 1);
        assert_eq!(lis_length(&[1, 1, 1, 1]), 1);
        assert_eq!(lis_length(&[0, 0, 1, 1, 2, 2]), 3);
        assert_eq!(lis_length(&[10, 9, 2, 5, 3, 7, 101, 18]), 4); // 2,3,7,18
        assert_eq!(lis_length(&[0, 1, 0, 3, 2, 3]), 4); // 0,1,2,3
        assert_eq!(lis_length(&[7, 7, 7, 7, 7, 7, 7]), 1);
        assert_eq!(lis_length(&[1, 3, 5, 4, 7]), 4); // 1,3,4,7
        assert_eq!(lis_length(&[i64::MIN, i64::MIN]), 1);
        assert_eq!(lis_length(&[i64::MIN, 0, i64::MAX]), 3);
        assert_eq!(lis_length(&[i64::MAX, i64::MIN]), 1);
        // 100 all-distinct increasing elements -> LIS is the whole array
        let inc: Vec<i64> = (0..100).map(|i| i as i64 * 2 - 1000).collect();
        assert_eq!(lis_length(&inc), 100);
        // 100 all-distinct decreasing elements -> LIS is 1
        let dec: Vec<i64> = (0..100).map(|i| 1000 - i as i64 * 2).collect();
        assert_eq!(lis_length(&dec), 1);
        // 100 identical elements -> LIS is 1
        let same: Vec<i64> = vec![-12345; 100];
        assert_eq!(lis_length(&same), 1);
    }

    #[test]
    fn matches_brute_force_on_fixed_cases() {
        let cases: Vec<Vec<i64>> = vec![
            vec![4, 1, 5, 3, 7, 6, 2],
            vec![2, 2, 2],
            vec![],
            vec![3, 1, 2, 1],
            vec![-2, -1, -2, 0, 0, 1],
            vec![5, 2, 8, 1, 9, 3, 10, 4, 11],
            vec![9, 1, 2, 4, 3, 4, 5],
            vec![1, 2, 2, 3, 3, 4],
            vec![-5, -5, -4, -6, -4, -3],
            vec![100, 50, 75, 25, 60, 80, 30, 90],
            vec![1, 7, 3, 5, 9, 4, 6, 8, 10, 2],
            vec![-1, 0, -1, 0, -1, 0],
        ];
        for c in &cases {
            assert_eq!(lis_length(c), brute_force(c), "mismatch on {:?}", c);
        }
    }

    proptest! {
        #[test]
        fn prop_matches_brute_force_small_values(
            // Small value domain to force lots of duplicates.
            values in prop::collection::vec(any::<i8>().prop_map(|v| v as i64), 0..=14)
        ) {
            let expected = brute_force(&values);
            prop_assert_eq!(lis_length(&values), expected);
        }

        #[test]
        fn prop_matches_brute_force_random_values(
            values in prop::collection::vec(any::<i64>(), 0..=10)
        ) {
            let expected = brute_force(&values);
            prop_assert_eq!(lis_length(&values), expected);
        }

        #[test]
        fn prop_matches_dp_reference_full_size(values in prop::collection::vec(any::<i64>(), 0..=100)) {
            prop_assert_eq!(lis_length(&values), dp_reference(&values));
        }

        #[test]
        fn prop_matches_dp_reference_biased_duplicates(
            values in prop::collection::vec(
                prop_oneof![any::<i64>(), any::<i8>().prop_map(|v| v as i64)],
                0..=100,
            )
        ) {
            prop_assert_eq!(lis_length(&values), dp_reference(&values));
        }

        #[test]
        fn prop_result_in_bounds(values in prop::collection::vec(any::<i64>(), 0..=100)) {
            let n = lis_length(&values);
            if values.is_empty() {
                prop_assert_eq!(n, 0);
            } else {
                prop_assert!((1..=values.len()).contains(&n));
            }
        }

        #[test]
        fn prop_sorted_input(values in prop::collection::vec(any::<i64>(), 0..=100)) {
            let mut v = values;
            v.sort_unstable();
            if v.is_empty() {
                prop_assert_eq!(lis_length(&v), 0);
            } else {
                // For a sorted array, LIS = 1 + number of strict adjacent increases.
                let increases = v.windows(2).filter(|w| w[1] > w[0]).count();
                prop_assert_eq!(lis_length(&v), 1 + increases);
            }
        }
    }
}

//! Lexicographic next-permutation over slices.

/// Rearranges `a` into the next permutation of its elements in
/// lexicographic order and returns `true`.
///
/// When `a` is already the last permutation (sorted in non-increasing
/// order), it is rearranged into the first permutation (sorted in
/// non-decreasing order) and `false` is returned.
///
/// Works correctly with repeated values.
pub fn next_permutation(a: &mut [i64]) -> bool {
    // 1. Find the largest index `i` such that a[i] < a[i + 1].
    let mut i = a.len().saturating_sub(1);
    let mut found = false;
    while i > 0 {
        i -= 1;
        if a[i] < a[i + 1] {
            found = true;
            break;
        }
    }
    if !found {
        // Already the last permutation: sort ascending (first permutation).
        a.reverse();
        return false;
    }

    // 2. Find the largest index `j > i` such that a[i] < a[j].
    //    The suffix a[i+1..] is non-increasing, so scanning from the end
    //    finds the rightmost element strictly greater than a[i].
    let mut j = a.len() - 1;
    while a[j] <= a[i] {
        j -= 1;
    }

    // 3. Swap a[i] and a[j].
    a.swap(i, j);

    // 4. Reverse the (non-increasing) suffix a[i+1..] to make it
    //    non-decreasing, yielding the smallest possible tail.
    a[i + 1..].reverse();

    true
}

#[cfg(test)]
mod tests {
    use super::next_permutation;
    use proptest::prelude::*;
    use std::collections::BTreeSet;

    /// Reference model: generate every distinct arrangement of `v`,
    /// sorted lexicographically (BTreeSet gives that order).
    fn all_permutations(v: &[i64]) -> BTreeSet<Vec<i64>> {
        let mut out = BTreeSet::new();
        let mut w = v.to_vec();
        gen(w.as_mut_slice(), 0, &mut out);
        out
    }

    fn gen(w: &mut [i64], k: usize, out: &mut BTreeSet<Vec<i64>>) {
        if k == w.len() {
            out.insert(w.to_vec());
            return;
        }
        for i in k..w.len() {
            w.swap(k, i);
            gen(w, k + 1, out);
            w.swap(k, i);
        }
    }

    /// Expected next permutation per the model, plus whether a next exists.
    fn expected_next(v: &[i64]) -> (Vec<i64>, bool) {
        let perms = all_permutations(v);
        if perms.is_empty() {
            return (Vec::new(), false);
        }
        let sorted: Vec<&Vec<i64>> = perms.iter().collect();
        let cur = v.to_vec();
        let idx = sorted
            .iter()
            .position(|p| **p == cur)
            .expect("current must be in permutation list");
        if idx + 1 < sorted.len() {
            (sorted[idx + 1].clone(), true)
        } else {
            (sorted[0].clone(), false)
        }
    }

    #[test]
    fn given_examples() {
        let mut a = [3, 2, 4, 1];
        assert_eq!(next_permutation(&mut a), true);
        assert_eq!(a, [3, 4, 1, 2]);

        let mut b = [3, 2, 1];
        assert_eq!(next_permutation(&mut b), false);
        assert_eq!(b, [1, 2, 3]);
    }

    #[test]
    fn duplicates_permutations_of_112() {
        // [1,1,2] -> [1,2,1] -> [2,1,1] -> [1,1,2]
        let mut a = [1, 1, 2];
        assert!(next_permutation(&mut a));
        assert_eq!(a, [1, 2, 1]);
        assert!(next_permutation(&mut a));
        assert_eq!(a, [2, 1, 1]);
        assert!(!next_permutation(&mut a));
        assert_eq!(a, [1, 1, 2]);
    }

    #[test]
    fn empty_and_single() {
        let mut a: [i64; 0] = [];
        assert!(!next_permutation(&mut a));

        let mut b = [42i64];
        assert!(!next_permutation(&mut b));
        assert_eq!(b, [42]);
    }

    #[test]
    fn all_equal() {
        let mut a = [7, 7, 7, 7];
        assert!(!next_permutation(&mut a));
        assert_eq!(a, [7, 7, 7, 7]);
    }

    #[test]
    fn non_increasing_with_duplicates() {
        // Non-increasing with repeated values: last permutation -> sorted.
        let mut a = [5, 5, 4, 2, 2];
        assert!(!next_permutation(&mut a));
        assert_eq!(a, [2, 2, 4, 5, 5]);
    }

    #[test]
    fn negative_and_mixed_values() {
        let mut a = [-2, 0, -2, -5];
        let (want, flag) = expected_next(&[-2, 0, -2, -5]);
        let got = next_permutation(&mut a);
        assert_eq!(got, flag);
        assert_eq!(a.to_vec(), want);
    }

    #[test]
    fn long_slices() {
        // 1000-element strictly decreasing slice: must become ascending, return false.
        let mut a: Vec<i64> = (0..1000i64).rev().collect();
        assert!(!next_permutation(&mut a));
        assert_eq!(a, (0..1000i64).collect::<Vec<_>>());

        // 1000-element ascending slice: only the last two elements swap.
        let mut b: Vec<i64> = (0..1000i64).collect();
        assert!(next_permutation(&mut b));
        let mut expected: Vec<i64> = (0..1000i64).collect();
        expected.swap(998, 999);
        assert_eq!(b, expected);

        // i64 extremes: no overflow concerns, pure ordering.
        let mut c = [i64::MAX, i64::MIN, 0];
        let (want, flag) = expected_next(&[i64::MAX, i64::MIN, 0]);
        assert_eq!(next_permutation(&mut c), flag);
        assert_eq!(c.to_vec(), want);
    }

    proptest! {
        #![proptest_config(ProptestConfig::with_cases(200))]
        #[test]
        fn matches_reference_model(mut v in prop::collection::vec(
            any::<i8>().prop_map(i64::from), 0..=8)) {
            let orig = v.clone();
            let (want, flag) = expected_next(&orig);
            let got = next_permutation(&mut v);
            prop_assert_eq!(got, flag);
            prop_assert_eq!(v, want);
        }

        #[test]
        fn cycle_visits_each_arrangement_once(v in prop::collection::vec(
            any::<u8>().prop_map(|n| [1, 2, 3, -1][(n % 4) as usize] as i64), 0..=8)) {
            let mut a = v.clone();
            let perms = all_permutations(&a);
            let n = perms.len();
            let last = perms.iter().last().cloned();
            let mut seen = BTreeSet::new();
            for _ in 0..n {
                // The flag is false exactly when the input is the last permutation.
                let input_was_last = last.as_ref().map(|p| *p == a).unwrap_or(true);
                let res = next_permutation(&mut a);
                prop_assert!(perms.contains(&a), "a became an invalid arrangement: {:?}", a);
                prop_assert!(!seen.contains(&a), "arrangement repeated: {:?}", a);
                seen.insert(a.clone());
                prop_assert_eq!(res, !input_was_last, "wrong flag for input {:?}", a);
            }
            prop_assert_eq!(a, v, "after a full cycle must return to the start");
        }
    }
}

//! Count the number of distinct ways (multisets of coins) to make `total`
//! from an unlimited supply of the given coin values.

/// Number of distinct ways to make exactly `total` using unlimited copies of
/// the coin values in `coins`, where order does not matter (ways are
/// multisets). There is exactly one way to make 0 (no coins).
pub fn count_change(coins: &[i64], total: i64) -> u64 {
    if total < 0 {
        return 0;
    }
    let n = total as usize;
    let mut dp = vec![0u64; n + 1];
    dp[0] = 1;
    // Outer loop over coins (so each multiset is counted once), inner loop
    // over amounts.
    for &c in coins {
        if c <= 0 {
            continue; // defensive: domain guarantees positive coin values
        }
        let c = c as usize;
        if c > n {
            continue;
        }
        for amt in c..=n {
            dp[amt] += dp[amt - c];
        }
    }
    dp[n]
}

#[cfg(test)]
mod tests {
    use super::count_change;
    use proptest::prelude::*;

    /// Independent reference: count multisets by fixing, coin by coin, how
    /// many of the current coin are used.
    fn brute(coins: &[i64], total: i64) -> u64 {
        fn rec(coins: &[i64], i: usize, remaining: i64) -> u64 {
            if i == coins.len() {
                return if remaining == 0 { 1 } else { 0 };
            }
            let mut sum = 0;
            let mut r = remaining;
            while r >= 0 {
                sum += rec(coins, i + 1, r);
                r -= coins[i];
            }
            sum
        }
        rec(coins, 0, total)
    }

    /// Strategy: up to `max_len` distinct coin values in `range`.
    fn distinct_coins(range: std::ops::RangeInclusive<usize>, max_len: usize) -> impl Strategy<Value = Vec<i64>> {
        prop::collection::vec(range, 0..=max_len).prop_map(|mut v| {
            v.sort_unstable();
            v.dedup();
            v.into_iter().map(|x| x as i64).collect()
        })
    }

    #[test]
    fn given_examples() {
        assert_eq!(count_change(&[1, 5, 10, 25], 11), 4);
        assert_eq!(count_change(&[2], 3), 0);
        assert_eq!(count_change(&[], 0), 1);
    }

    #[test]
    fn zero_and_edges() {
        assert_eq!(count_change(&[1, 5, 10, 25], 0), 1);
        assert_eq!(count_change(&[], 7), 0);
        assert_eq!(count_change(&[1], 0), 1);
        assert_eq!(count_change(&[1], 5), 1);
        assert_eq!(count_change(&[500], 500), 1);
        assert_eq!(count_change(&[500], 499), 0);
        assert_eq!(count_change(&[1000], 500), 0); // coin larger than total
    }

    #[test]
    fn hand_checked_values() {
        // {2,2,2}, {3,3}
        assert_eq!(count_change(&[2, 3], 6), 2);
        // 0, 1 or 2 twos with pennies filling the rest
        assert_eq!(count_change(&[1, 2], 5), 3);
        // {3,3,3}, {4,5}
        assert_eq!(count_change(&[3, 4, 5], 9), 2);
        // order of the coin list must not matter
        assert_eq!(count_change(&[3, 4, 5], 9), count_change(&[5, 3, 4], 9));
        // classic US coin problem: ways to make a dollar
        assert_eq!(count_change(&[1, 5, 10, 25], 100), 242);
    }

    #[test]
    fn order_of_coins_does_not_matter_medium() {
        let a = count_change(&[1, 5, 10, 25], 200);
        let b = count_change(&[25, 1, 10, 5], 200);
        assert_eq!(a, b);
        assert!(a > 0);
    }

    #[test]
    fn large_worst_case_does_not_overflow() {
        // 12 smallest coins, max total: worst case for u64 intermediates.
        let coins: Vec<i64> = (1..=12).collect();
        let v = count_change(&coins, 500);
        assert!(v > 0);
        assert!(v < u64::MAX / 4); // sanity: well inside range
    }

    #[test]
    fn gcd_zero_property() {
        // total not divisible by gcd of coins => 0 ways
        let coins = vec![6, 10, 15];
        assert_eq!(count_change(&coins, 7), 0);
        assert_eq!(count_change(&coins, 9), 0);
        assert_eq!(count_change(&coins, 14), 0);
        // 6a + 10b + 15c = 30: {a=5,b=0,c=0}, {a=0,b=3,c=0}, {c=2} => 3
        assert_eq!(count_change(&coins, 30), 3);
    }

    proptest! {
        /// Small random cases against the brute-force reference.
        #[test]
        fn matches_brute(coins in distinct_coins(1..=30, 6), total in 0i64..=80) {
            let c: Vec<i64> = coins;
            prop_assert_eq!(count_change(&c, total), brute(&c, total));
        }

        /// Full domain: up to 12 distinct coins in 1..=500, total 0..=500.
        /// Cross-checks against the brute force when that is affordable.
        #[test]
        fn full_domain_check(coins in distinct_coins(1..=500, 12), total in 0i64..=500) {
            let c: Vec<i64> = coins;
            let got = count_change(&c, total);
            // If the coin list is small, verify against brute force.
            if c.len() <= 7 {
                prop_assert_eq!(got, brute(&c, total));
            } else {
                prop_assert!(got <= u64::MAX);
            }
        }

        /// Commutativity in the coin list on medium inputs.
        #[test]
        fn coin_order_invariant(seed in any::<u64>()) {
            let base: [i64; 8] = [1, 3, 4, 7, 11, 13, 29, 50];
            // build a deterministic permutation from seed
            let mut v = base.to_vec();
            let mut x = seed | 1;
            for i in (1..v.len()).rev() {
                x = x.wrapping_mul(6364136223846793005).wrapping_add(1442695040888963407);
                let j = ((x >> 33) as usize) % (i + 1);
                v.swap(i, j);
            }
            let t = (seed % 300) as i64;
            prop_assert_eq!(count_change(&v, t), count_change(&base, t));
        }

        /// With a penny present, the number of ways is non-decreasing in total
        /// (removing one penny maps each way(t) to a way(t-1), surjectively).
        #[test]
        fn monotone_with_penny(coins in distinct_coins(2..=40, 5), t in 0i64..=250) {
            let mut c = vec![1i64];
            c.extend_from_slice(&coins);
            if t < 250 {
                prop_assert!(count_change(&c, t) <= count_change(&c, t + 1));
            }
        }
    }
}

//! 0/1 knapsack: each item may be taken at most once; maximize total value
//! subject to a total weight limit.

/// Returns the largest total value of a subset of items whose total weight is
/// at most `capacity` (0 when nothing fits).
///
/// Items `i` have weight `weights[i]` and value `values[i]`; the slices have
/// the same length (at most 30), `capacity <= 1000`, weights are in `1..=1000`
/// and values in `0..=1_000_000_000_000_000`, so all totals fit in `i64`.
pub fn knapsack(capacity: usize, weights: &[i64], values: &[i64]) -> i64 {
    // dp[w] = best total value achievable with total weight at most w.
    let mut dp = vec![0i64; capacity + 1];

    for (&w_i, &v_i) in weights.iter().zip(values) {
        // Domain guarantees w_i >= 1; skip items that are too heavy.
        let w = w_i as usize;
        if w > capacity {
            continue;
        }
        // Descending order so each item is used at most once.
        for cap in (w..=capacity).rev() {
            let candidate = dp[cap - w] + v_i;
            if candidate > dp[cap] {
                dp[cap] = candidate;
            }
        }
    }

    dp[capacity]
}

#[cfg(test)]
mod tests {
    use super::*;
    use proptest::prelude::*;

    /// O(2^n) reference for small inputs.
    fn brute(capacity: usize, weights: &[i64], values: &[i64]) -> i64 {
        let n = weights.len();
        let mut best = 0i64;
        for mask in 0..1usize.checked_shl(n as u32).unwrap() {
            let mut w = 0usize;
            let mut v = 0i64;
            for i in 0..n {
                if mask >> i & 1 == 1 {
                    w += weights[i] as usize;
                    v += values[i];
                }
            }
            if w <= capacity && v > best {
                best = v;
            }
        }
        best
    }

    #[test]
    fn given_examples() {
        assert_eq!(
            knapsack(100, &[60, 50, 20, 20, 8, 3], &[10, 8, 4, 4, 3, 2]),
            19
        );
        assert_eq!(knapsack(5, &[5], &[7]), 7);
    }

    #[test]
    fn nothing_fits_and_zero_capacity() {
        assert_eq!(knapsack(3, &[5, 6], &[100, 200]), 0);
        assert_eq!(knapsack(0, &[1, 2], &[7, 9]), 0);
    }

    #[test]
    fn empty_item_list() {
        assert_eq!(knapsack(10, &[], &[]), 0);
    }

    #[test]
    fn item_heavier_than_capacity_is_skipped() {
        // weight 1000 > capacity 999, but the other items fit
        assert_eq!(knapsack(999, &[1000, 1000, 499], &[5, 5, 7]), 7);
    }

    #[test]
    fn zero_value_items() {
        assert_eq!(knapsack(10, &[3, 3, 3], &[0, 0, 0]), 0);
    }

    #[test]
    fn large_values_no_overflow() {
        // 30 items of weight 1, each value 1e15 -> total 3e16 < i64::MAX.
        let big = 1_000_000_000_000_000i64;
        let weights = vec![1; 30];
        let values = vec![big; 30];
        assert_eq!(knapsack(1000, &weights, &values), 30 * big);
        // capacity only 10 -> take 10 items
        assert_eq!(knapsack(10, &weights, &values), 10 * big);
    }

    proptest! {
        #[test]
        fn prop_matches_bruteforce(
            capacity in 0..=80usize,
            items in proptest::collection::vec(
                (1i64..=120, 0i64..=1_000_000_000_000),
                0..=13usize,
            ),
        ) {
            let weights: Vec<i64> = items.iter().map(|(w, _)| *w).collect();
            let values: Vec<i64> = items.iter().map(|(_, v)| *v).collect();
            prop_assert_eq!(
                knapsack(capacity, &weights, &values),
                brute(capacity, &weights, &values)
            );
        }

        #[test]
        fn prop_at_most_one_copy_of_each_item(
            capacity in 30..=60usize,
        ) {
            // 20 identical items (w=5, v=10): best is exactly capacity/5 of
            // them, so a buggy "unbounded" DP would return more.
            let weights = vec![5; 20];
            let values = vec![10; 20];
            let got = knapsack(capacity, &weights, &values);
            let expected = (capacity / 5) * 10;
            prop_assert_eq!(got, expected as i64);
        }
    }
}

/// Returns the Levenshtein distance between the sequences `a` and `b`:
/// the least number of single-element edits (insert an element, delete an
/// element, or replace an element by another) that turn `a` into `b`.
pub fn edit_distance(a: &[i64], b: &[i64]) -> usize {
    // The distance is symmetric; keep the shorter slice as the rolling row
    // to use a little less memory.
    let (a, b) = if a.len() >= b.len() { (a, b) } else { (b, a) };
    let n = a.len();
    let m = b.len();
    debug_assert!(n >= m); // a is the longer (or equal) slice

    // prev[j] = distance between a[..i]   and b[..j]
    // curr[j] = distance between a[..i+1] and b[..j]
    let mut prev: Vec<usize> = (0..=m).collect();
    let mut curr: Vec<usize> = vec![0; m + 1];

    for i in 1..=n {
        curr[0] = i; // delete all i elements of a[..i]
        for j in 1..=m {
            let cost = if a[i - 1] == b[j - 1] { 0 } else { 1 };
            curr[j] = (prev[j] + 1) // delete a[i-1]
                .min(curr[j - 1] + 1) // insert b[j-1]
                .min(prev[j - 1] + cost); // keep / replace
        }
        std::mem::swap(&mut prev, &mut curr);
    }

    prev[m]
}

#[cfg(test)]
mod tests {
    use super::edit_distance;
    use proptest::prelude::*;

    #[test]
    fn examples() {
        assert_eq!(edit_distance(&[1, 2, 3], &[1, 3]), 1);
        assert_eq!(edit_distance(&[5, 6], &[7, 8]), 2);
        assert_eq!(edit_distance(&[], &[4, 4]), 2);
        assert_eq!(edit_distance(&[], &[]), 0);
        assert_eq!(edit_distance(&[4, 4], &[]), 2);
        assert_eq!(edit_distance(&[7, 8], &[5, 6]), 2);
    }

    #[test]
    fn identity_and_trivial() {
        let v: Vec<i64> = (0..64).collect();
        assert_eq!(edit_distance(&v, &v), 0);
        assert_eq!(edit_distance(&v, &[]), 64);
        assert_eq!(edit_distance(&[], &v), 64);
        let other: Vec<i64> = (0..64).map(|x| x + 1000).collect();
        assert_eq!(edit_distance(&v, &other), 64);
    }

    #[test]
    fn classic_words() {
        let s = |w: &str| -> Vec<i64> { w.chars().map(|c| c as i64).collect() };
        assert_eq!(edit_distance(&s("kitten"), &s("sitting")), 3);
        assert_eq!(edit_distance(&s("flaw"), &s("lawn")), 2);
        assert_eq!(edit_distance(&s("sunday"), &s("saturday")), 3);
    }

    proptest! {
        /// Symmetry: d(a, b) == d(b, a).
        #[test]
        fn symmetry(
            a in prop::collection::vec(any::<i64>(), 0..=64),
            b in prop::collection::vec(any::<i64>(), 0..=64),
        ) {
            assert_eq!(edit_distance(&a, &b), edit_distance(&b, &a));
        }

        /// Triangle inequality: d(a, c) <= d(a, b) + d(b, c).
        #[test]
        fn triangle(
            a in prop::collection::vec(any::<i64>(), 0..=32),
            b in prop::collection::vec(any::<i64>(), 0..=32),
            c in prop::collection::vec(any::<i64>(), 0..=32),
        ) {
            let dab = edit_distance(&a, &b);
            let dbc = edit_distance(&b, &c);
            let dac = edit_distance(&a, &c);
            assert!(dac <= dab + dbc);
        }

        /// Distance never exceeds max(len) (replace all + length difference).
        #[test]
        fn bounded(
            a in prop::collection::vec(any::<i64>(), 0..=64),
            b in prop::collection::vec(any::<i64>(), 0..=64),
        ) {
            let d = edit_distance(&a, &b);
            assert!(d <= a.len().max(b.len()));
        }

        /// Against a brute-force recursive reference implementation.
        #[test]
        fn matches_bruteforce(
            a in prop::collection::vec(any::<i64>(), 0..=9),
            b in prop::collection::vec(any::<i64>(), 0..=9),
        ) {
            assert_eq!(edit_distance(&a, &b), brute(&a, &b));
        }
    }

    /// Reference implementation via memoized recursion over suffixes
    /// (fine for the small lengths used in the property test).
    fn brute(a: &[i64], b: &[i64]) -> usize {
        use std::collections::HashMap;
        fn rec(
            a: &[i64],
            b: &[i64],
            i: usize,
            j: usize,
            memo: &mut HashMap<(usize, usize), usize>,
        ) -> usize {
            if i == a.len() {
                return b.len() - j;
            }
            if j == b.len() {
                return a.len() - i;
            }
            if let Some(&v) = memo.get(&(i, j)) {
                return v;
            }
            let v = if a[i] == b[j] {
                rec(a, b, i + 1, j + 1, memo)
            } else {
                rec(a, b, i + 1, j + 1, memo) + 1 // replace
                    .min(rec(a, b, i + 1, j, memo) + 1) // delete
                    .min(rec(a, b, i, j + 1, memo) + 1) // insert
            };
            memo.insert((i, j), v);
            v
        }
        let mut memo = HashMap::new();
        rec(a, b, 0, 0, &mut memo)
    }
}

/// Returns the length of the longest run of consecutive elements that
/// appears in both `a` and `b` (longest common *substring*, not subsequence).
///
/// Examples:
/// - `common_substring(&[1, 2, 3, 4], &[9, 2, 3, 9]) == 2`
/// - `common_substring(&[1, 2], &[3]) == 0`
pub fn common_substring(a: &[i64], b: &[i64]) -> usize {
    if a.is_empty() || b.is_empty() {
        return 0;
    }

    let mut best = 0usize;
    // prev[j] = length of the longest common suffix of a[..=i-1] and b[..=j]
    let mut prev = vec![0usize; b.len()];

    for &x in a {
        let mut cur = vec![0usize; b.len()];
        for (j, &y) in b.iter().enumerate() {
            if x == y {
                let v = if j == 0 { 1 } else { prev[j - 1] + 1 };
                cur[j] = v;
                if v > best {
                    best = v;
                }
            }
        }
        std::mem::swap(&mut prev, &mut cur);
    }

    best
}

#[cfg(test)]
mod tests {
    use super::common_substring;
    use proptest::prelude::*;

    #[test]
    fn examples_from_statement() {
        assert_eq!(common_substring(&[1, 2, 3, 4], &[9, 2, 3, 9]), 2);
        assert_eq!(common_substring(&[1, 2], &[3]), 0);
    }

    #[test]
    fn empty_slices() {
        assert_eq!(common_substring(&[], &[]), 0);
        assert_eq!(common_substring(&[], &[1, 2, 3]), 0);
        assert_eq!(common_substring(&[1, 2, 3], &[]), 0);
    }

    #[test]
    fn single_elements() {
        assert_eq!(common_substring(&[5], &[5]), 1);
        assert_eq!(common_substring(&[5], &[6]), 0);
        assert_eq!(common_substring(&[1], &[1, 2, 3]), 1);
    }

    #[test]
    fn whole_slice_match() {
        let v = [1, 2, 3, 4, 5];
        assert_eq!(common_substring(&v, &v), 5);
        assert_eq!(common_substring(&v, &[0, 1, 2, 3, 4, 5, 0]), 5);
        assert_eq!(common_substring(&[0, 1, 2, 3, 4, 5, 0], &v), 5);
    }

    #[test]
    fn repeated_elements() {
        assert_eq!(common_substring(&[1, 1, 1, 1], &[1, 1]), 2);
        assert_eq!(common_substring(&[1, 1, 1], &[1, 1, 1, 1, 1]), 3);
        assert_eq!(common_substring(&[1, 2, 1, 2, 1, 2], &[2, 1, 2]), 3);
    }

    #[test]
    fn adjacent_vs_interleaved() {
        // [1,2,3] in a, but only [1,3] in b -> common run is 1
        assert_eq!(common_substring(&[1, 2, 3], &[1, 3]), 1);
        // order matters: it's a substring, not a subsequence
        assert_eq!(common_substring(&[1, 2], &[2, 1]), 1);
        assert_eq!(common_substring(&[1, 2, 3], &[3, 2, 1]), 1);
        // reversed adjacency gives a run of 1
        assert_eq!(common_substring(&[i64::MIN, 0, i64::MAX], &[i64::MAX, 0]), 1);
    }

    #[test]
    fn negative_and_extreme_values() {
        assert_eq!(common_substring(&[i64::MIN, i64::MAX, 0], &[i64::MAX, 0]), 2);
        assert_eq!(common_substring(&[-5, -4, -3], &[10, -4, -3, 20]), 2);
        assert_eq!(common_substring(&[i64::MIN], &[i64::MIN]), 1);
    }

    #[test]
    fn max_size_input() {
        let a: Vec<i64> = (0..64).collect();
        let b: Vec<i64> = (10..74).collect();
        assert_eq!(common_substring(&a, &b), 54);
        let c: Vec<i64> = (0..64).rev().collect();
        // a and c share only single elements (no 2-run), since adjacent values differ
        assert_eq!(common_substring(&a, &c), 1);
    }

    /// Brute-force reference: largest `len` such that some consecutive
    /// `a[i..i+len]` equals some `b[j..j+len]`.
    fn brute(a: &[i64], b: &[i64]) -> usize {
        let (n, m) = (a.len(), b.len());
        let mut best = 0;
        for len in 1..=n.min(m) {
            let mut found = false;
            'outer: for i in 0..=n - len {
                for j in 0..=m - len {
                    if a[i..i + len] == b[j..j + len] {
                        found = true;
                        break 'outer;
                    }
                }
            }
            if found {
                best = len;
            }
        }
        best
    }

    proptest! {
        #[test]
        fn matches_brute_force(
            a in prop::collection::vec(any::<i64>(), 0..=12),
            b in prop::collection::vec(any::<i64>(), 0..=12),
        ) {
            assert_eq!(common_substring(&a, &b), brute(&a, &b));
        }

        #[test]
        fn small_alphabet_longer_slices(
            a in prop::collection::vec(0..=4i64, 0..=30),
            b in prop::collection::vec(0..=4i64, 0..=30),
        ) {
            assert_eq!(common_substring(&a, &b), brute(&a, &b));
        }

        #[test]
        fn bound_by_lengths(
            a in prop::collection::vec(any::<i64>(), 0..=64),
            b in prop::collection::vec(any::<i64>(), 0..=64),
        ) {
            let r = common_substring(&a, &b);
            assert!(r <= a.len().min(b.len()));
            // symmetric
            assert_eq!(r, common_substring(&b, &a));
        }
    }
}

/// Returns the number of primes p with p <= n.
///
/// For example: `count_primes(10) == 4` (2, 3, 5, 7), `count_primes(2) == 1`,
/// `count_primes(1) == 0`.
pub fn count_primes(n: u64) -> u64 {
    if n < 2 {
        return 0;
    }
    let limit = n as usize;
    // Sieve of Eratosthenes.
    let mut is_prime = vec![true; limit + 1];
    is_prime[0] = false;
    is_prime[1] = false;
    let mut i = 2;
    while (i as u64) * (i as u64) <= n {
        if is_prime[i] {
            let mut j = i * i;
            while j <= limit {
                is_prime[j] = false;
                j += i;
            }
        }
        i += 1;
    }
    is_prime.iter().filter(|&&p| p).count() as u64
}

#[cfg(test)]
mod tests {
    use super::count_primes;

    /// Brute-force reference: trial division per candidate.
    fn is_prime_brute(x: u64) -> bool {
        if x < 2 {
            return false;
        }
        if x < 4 {
            return true; // 2 and 3
        }
        if x % 2 == 0 {
            return false;
        }
        let mut d = 3;
        while d * d <= x {
            if x % d == 0 {
                return false;
            }
            d += 2;
        }
        true
    }

    fn count_primes_brute(n: u64) -> u64 {
        (2..=n).filter(|&x| is_prime_brute(x)).count() as u64
    }

    #[test]
    fn known_values() {
        assert_eq!(count_primes(0), 0);
        assert_eq!(count_primes(1), 0);
        assert_eq!(count_primes(2), 1);
        assert_eq!(count_primes(3), 2);
        assert_eq!(count_primes(4), 2);
        assert_eq!(count_primes(10), 4);
        assert_eq!(count_primes(100), 25);
        assert_eq!(count_primes(1000), 168);
        assert_eq!(count_primes(10000), 1229);
        assert_eq!(count_primes(20000), 2262);
        assert_eq!(count_primes(100000), 9592); // just above domain, still fine
    }

    #[test]
    fn exhaustive_up_to_5000() {
        for n in 0..=5000u64 {
            assert_eq!(count_primes(n), count_primes_brute(n));
        }
    }

    proptest::proptest! {
        #[test]
        fn matches_brute_force(n in 0u64..=20000) {
            assert_eq!(count_primes(n), count_primes_brute(n));
        }
    }
}

/// Sort `a` in non-decreasing order in place using counting sort.
///
/// Every element of `a` is in `0..k` (each is at least 0 and less than `k`),
/// and `1 <= k <= 64`. All elements (duplicates included) are preserved.
///
/// The slice is sorted in place: the counts of the input are used to
/// rebuild the slice, so the only auxiliary storage is a count table of
/// size `k` (at most 64).
pub fn counting_sort(a: &mut [i64], k: i64) {
    debug_assert!(k >= 1, "k must be at least 1");
    debug_assert!(a.iter().all(|&x| (0..k).contains(&x)), "all elements must be in 0..k");

    // Count occurrences of each value in 0..k.
    let mut counts = vec![0i64; k as usize];
    for &x in a.iter() {
        counts[x as usize] += 1;
    }

    // Rewrite the slice in place from the counts: the sorted output is
    // fully determined by the counts (value v appears counts[v] times),
    // so filling `a` sequentially never disturbs data we still need.
    // `pos` always stays within 0..=a.len() because the counts sum to
    // a.len().
    let mut pos = 0usize;
    for v in 0..k as usize {
        let c = counts[v] as usize;
        for _ in 0..c {
            a[pos] = v as i64;
            pos += 1;
        }
    }
}

#[cfg(test)]
mod tests {
    use super::counting_sort;
    use proptest::prelude::*;

    #[test]
    fn example_from_statement() {
        let mut a = [3i64, 0, 3, 1];
        counting_sort(&mut a, 5);
        assert_eq!(a, [0, 1, 3, 3]);
    }

    #[test]
    fn empty_slice() {
        let mut a: [i64; 0] = [];
        counting_sort(&mut a, 1);
        assert_eq!(a, []);
    }

    #[test]
    fn single_element() {
        let mut a = [0i64];
        counting_sort(&mut a, 1);
        assert_eq!(a, [0]);
    }

    #[test]
    fn k_eq_1_only_zeros() {
        let mut a = [0i64, 0, 0, 0, 0];
        counting_sort(&mut a, 1);
        assert_eq!(a, [0, 0, 0, 0, 0]);
    }

    #[test]
    fn already_sorted() {
        let mut a = [0i64, 0, 1, 2, 2, 2, 3, 4, 4];
        counting_sort(&mut a, 5);
        assert_eq!(a, [0, 0, 1, 2, 2, 2, 3, 4, 4]);
    }

    #[test]
    fn reverse_sorted() {
        let mut a = [4i64, 3, 3, 2, 1, 0, 0];
        counting_sort(&mut a, 5);
        assert_eq!(a, [0, 0, 1, 2, 3, 3, 4]);
    }

    #[test]
    fn all_duplicates() {
        let mut a = [7i64, 7, 7, 7];
        counting_sort(&mut a, 8);
        assert_eq!(a, [7, 7, 7, 7]);
    }

    #[test]
    fn values_at_boundaries() {
        // 0 and k-1 are the only possible values.
        let mut a = [4i64, 0, 4, 0, 4];
        counting_sort(&mut a, 5);
        assert_eq!(a, [0, 0, 4, 4, 4]);
    }

    #[test]
    fn max_k_and_length() {
        // k = 64, 1000 elements covering the whole range.
        let mut a: Vec<i64> = (0..1000i64).map(|i| (i * 17) % 64).collect();
        let expected: Vec<i64> = {
            let mut e = a.clone();
            e.sort_unstable();
            e
        };
        counting_sort(&mut a, 64);
        assert_eq!(a, expected);
    }

    /// Generate (k, a) where k in 1..=64 and every element of a is in 0..k.
    fn gen_inputs() -> impl Strategy<Value = (i64, Vec<i64>)> {
        (1i64..=64, prop::collection::vec(0i64..64, 0..=1000)).prop_map(|(k, raw)| {
            let a = raw.into_iter().map(|x| x % k).collect::<Vec<i64>>();
            (k, a)
        })
    }

    proptest! {
        #[test]
        fn prop_matches_sorted_clone((k, mut a) in gen_inputs()) {
            let expected: Vec<i64> = {
                let mut e = a.clone();
                e.sort_unstable();
                e
            };
            counting_sort(&mut a, k);
            prop_assert_eq!(a, expected);
        }

        #[test]
        fn prop_non_decreasing_and_multiset_preserved((k, a) in gen_inputs()) {
            // Build the expected output directly from counts of the original.
            let mut counts = vec![0i64; k as usize];
            for &x in a.iter() {
                counts[x as usize] += 1;
            }
            let mut expected: Vec<i64> = Vec::with_capacity(a.len());
            for (v, &c) in counts.iter().enumerate() {
                expected.extend(std::iter::repeat(v as i64).take(c as usize));
            }

            let mut b = a.clone();
            counting_sort(&mut b, k);

            // Non-decreasing.
            prop_assert!(b.windows(2).all(|w| w[0] <= w[1]));
            // Same multiset as input, i.e. equals the count-expanded output.
            prop_assert_eq!(b, expected);
        }
    }
}

/// Returns `true` when the parenthesis sequence `p` is properly nested:
/// every closing parenthesis (`-1`) closes an earlier unclosed opening one
/// (`1`), and none is left open at the end.
///
/// Examples:
/// - `balanced(&[1, 1, -1, -1])` == `true`
/// - `balanced(&[-1, 1])` == `false`
/// - `balanced(&[1])` == `false`
/// - `balanced(&[])` == `true`
pub fn balanced(p: &[i64]) -> bool {
    let mut depth: i64 = 0;
    for &x in p {
        match x {
            1 => depth += 1,
            -1 => {
                if depth == 0 {
                    return false;
                }
                depth -= 1;
            }
            // Values outside the stated input domain are not a valid
            // parenthesis sequence.
            _ => return false,
        }
    }
    depth == 0
}

#[cfg(test)]
mod tests {
    use super::*;
    use proptest::prelude::*;

    /// Independent reference implementation via prefix sums:
    /// balanced iff every prefix sum is >= 0 and the total sum is 0.
    fn reference(p: &[i64]) -> bool {
        let mut sum = 0i64;
        for &x in p {
            sum += x;
            if sum < 0 {
                return false;
            }
        }
        sum == 0
    }

    /// Strategy producing a single element, uniformly 1 or -1.
    fn one_or_minus_one() -> impl proptest::strategy::Strategy<Value = i64> {
        prop_oneof![Just(1i64), Just(-1i64)]
    }

    #[test]
    fn examples() {
        assert!(balanced(&[1, 1, -1, -1]));
        assert!(!balanced(&[-1, 1]));
        assert!(!balanced(&[1]));
        assert!(balanced(&[]));
    }

    #[test]
    fn more_cases() {
        assert!(balanced(&[1, -1]));
        assert!(balanced(&[1, 1, 1, -1, -1, -1]));
        assert!(balanced(&[1, 1, -1, 1, -1, -1]));
        assert!(!balanced(&[-1, -1]));
        assert!(!balanced(&[1, 1, -1]));
        assert!(!balanced(&[1, -1, -1, 1]));
        assert!(!balanced(&[1, -1, 1]));
        assert!(!balanced(&[-1]));
        assert!(!balanced(&[1, 1, -1, 1, -1]));
    }

    /// Deterministically check that `balanced` agrees with the reference for
    /// EVERY sequence of length up to 10.
    #[test]
    fn exhaustive_small() {
        for len in 0..=10 {
            for mask in 0..(1usize << len) {
                let seq: Vec<i64> = (0..len)
                    .map(|i| if mask & (1 << i) != 0 { 1 } else { -1 })
                    .collect();
                assert_eq!(
                    balanced(&seq),
                    reference(&seq),
                    "mismatch for {seq:?}"
                );
            }
        }
    }

    proptest! {
        // Random property test (length up to 1000, matching the input
        // domain) against the prefix-sum reference.
        #[test]
        fn random_property_against_reference(
            seq in prop::collection::vec(one_or_minus_one(), 0..1000),
        ) {
            assert_eq!(balanced(&seq), reference(&seq), "mismatch for len {}", seq.len());
        }

        // Sequences generated by only legal moves (open a new paren, or
        // close an unclosed one), then closing everything left open, are
        // always valid and must be accepted.
        #[test]
        fn accepts_generated_valid(seed in any::<u32>()) {
            let mut rng_state = seed.wrapping_add(1);
            let mut rand = || {
                rng_state ^= rng_state << 13;
                rng_state ^= rng_state >> 17;
                rng_state ^= rng_state << 5;
                rng_state
            };

            let mut seq: Vec<i64> = Vec::new();
            let mut open: u32 = 0;
            for _ in 0..1000 {
                let r = rand() % 4;
                if r < 2 && open < 500 {
                    seq.push(1);
                    open += 1;
                } else if open > 0 {
                    seq.push(-1);
                    open -= 1;
                }
            }
            while open > 0 {
                seq.push(-1);
                open -= 1;
            }
            assert!(balanced(&seq));
        }

        // Any sequence with a leading `-1` is invalid.
        #[test]
        fn rejects_leading_close(
            rest in prop::collection::vec(one_or_minus_one(), 0..1000),
        ) {
            let mut seq: Vec<i64> = vec![-1];
            seq.extend(rest);
            assert!(!balanced(&seq));
        }
    }

    /// Long sequence stress tests at the domain limit (1000 elements).
    #[test]
    fn long_sequences() {
        let mut seq: Vec<i64> = Vec::with_capacity(1000);
        for _ in 0..500 {
            seq.push(1);
            seq.push(-1);
        }
        assert!(balanced(&seq));

        seq.clear();
        for _ in 0..500 {
            seq.push(1);
        }
        for _ in 0..500 {
            seq.push(-1);
        }
        assert!(balanced(&seq));

        // off by one at the end (unclosed opener)
        seq.pop();
        assert!(!balanced(&seq));
        // one too many closers in total
        seq.push(-1);
        seq.push(-1);
        assert!(!balanced(&seq));
    }
}

//! Binomial coefficients.

/// Returns the binomial coefficient `C(n, k)`: the number of ways to
/// choose `k` items out of `n` (entry `k` of row `n` of Pascal's triangle).
///
/// Returns `0` when `k > n`.
///
/// Input domain: `n <= 67`, so every result fits in `u64`
/// (the largest is `C(67, 33) = 14_226_520_737_620_288_370 < u64::MAX`).
pub fn binomial(n: u64, k: u64) -> u64 {
    if k > n {
        return 0;
    }

    // C(n, k) = C(n, n - k); iterate up to the smaller of the two.
    let k = k.min(n - k);

    // Multiplicative form: C(n, k) = prod_{i = 0}^{k-1} (n - i) / (i + 1).
    //
    // The division is exact at every step: after `i` iterations the
    // accumulator holds C(n, i), and
    //     (i + 1) * C(n, i + 1) = C(n, i) * (n - i),
    // so `acc * (n - i)` is always divisible by `i + 1`.
    //
    // Accumulate in `u128`: the intermediate product `C(n, i) * (n - i)`
    // can exceed `u64::MAX` even though the final result fits — e.g.
    // C(67, 32) * 35 ≈ 4.7e20 > u64::MAX ≈ 1.8e19. `u128` has plenty of
    // headroom for the whole domain (max intermediate ≈ 4.7e20 ≪ 3.4e38).
    let mut acc: u128 = 1;
    for i in 0..k {
        acc = acc * (n - i) as u128 / (i + 1) as u128;
    }

    // Within the stated domain (n <= 67) the result is < u64::MAX.
    acc as u64
}

#[cfg(test)]
mod tests {
    use super::binomial;

    /// Reference implementation via Pascal's triangle.
    ///
    /// For `n <= 67` no entry can overflow `u64`: every entry in rows
    /// `0..=n` with column `<= n/2` is at most `C(67, 33) < u64::MAX`.
    fn ref_binomial(n: u64, k: u64) -> u64 {
        if k > n {
            return 0;
        }
        let k = k.min(n - k);
        let mut row: Vec<u64> = vec![1];
        for i in 1..=n {
            let i = i as usize;
            let mut next: Vec<u64> = Vec::with_capacity(i + 1);
            next.push(1);
            for j in 1..i {
                next.push(row[j - 1] + row[j]);
            }
            next.push(1);
            row = next;
        }
        row[k as usize]
    }

    #[test]
    fn examples() {
        assert_eq!(binomial(5, 2), 10);
        assert_eq!(binomial(4, 0), 1);
        assert_eq!(binomial(3, 4), 0);
    }

    #[test]
    fn edge_cases() {
        assert_eq!(binomial(0, 0), 1);
        assert_eq!(binomial(0, 1), 0);
        assert_eq!(binomial(0, 100), 0);
        assert_eq!(binomial(1, 0), 1);
        assert_eq!(binomial(1, 1), 1);
        assert_eq!(binomial(1, 2), 0);
        assert_eq!(binomial(2, 1), 2);
        assert_eq!(binomial(67, 0), 1);
        assert_eq!(binomial(67, 1), 67);
        assert_eq!(binomial(67, 66), 67);
        assert_eq!(binomial(67, 67), 1);
        assert_eq!(binomial(67, 68), 0);
        assert_eq!(binomial(67, u64::MAX), 0);
    }

    #[test]
    fn known_values() {
        assert_eq!(binomial(10, 3), 120);
        assert_eq!(binomial(20, 10), 184_756);
        assert_eq!(binomial(30, 15), 155_117_520);
        assert_eq!(binomial(40, 20), 137_846_528_820);
        assert_eq!(binomial(60, 30), 118_264_581_564_861_424);
        // Largest value in the domain; must fit in u64 and equal its
        // symmetric counterpart C(67, 34).
        assert_eq!(binomial(67, 33), 14_226_520_737_620_288_370);
        assert_eq!(binomial(67, 33), binomial(67, 34));
        assert!(binomial(67, 33) < u64::MAX);
    }

    #[test]
    fn exhaustive_against_reference() {
        // Check every n in the domain against the reference, with k both
        // inside and outside the domain of row n (including huge k).
        for n in 0..=67u64 {
            for k in 0..=135u64 {
                assert_eq!(
                    binomial(n, k),
                    ref_binomial(n, k),
                    "binomial({}, {}) mismatch",
                    n,
                    k
                );
            }
            assert_eq!(binomial(n, u64::MAX), 0);
            assert_eq!(binomial(n, n + 1), 0);
        }
    }

    use proptest::prelude::*;

    proptest! {
        /// The fast implementation must agree with Pascal's triangle for
        /// any k in the full u64 range (k > n included).
        #[test]
        fn prop_matches_reference(n in 0u64..=67, k in any::<u64>()) {
            prop_assert_eq!(binomial(n, k), ref_binomial(n, k));
        }

        /// Symmetry C(n, k) = C(n, n - k) for k <= n, and 0 for k > n.
        #[test]
        fn prop_symmetry_and_zero(n in 0u64..=67, k in 0u64..=200) {
            if k <= n {
                prop_assert_eq!(binomial(n, k), binomial(n, n - k));
            } else {
                prop_assert_eq!(binomial(n, k), 0);
            }
        }

        /// Pascal's recurrence: C(n, k) = C(n-1, k-1) + C(n-1, k).
        /// (Addition done in u128; the sum equals C(n, k) which fits.)
        #[test]
        fn prop_pascal_recurrence(n in 2u64..=67, k in 0u64..=200) {
            if k <= n {
                let a = binomial(n - 1, k - 1);
                let b = binomial(n - 1, k);
                prop_assert_eq!(a as u128 + b as u128, binomial(n, k) as u128);
            } else {
                prop_assert_eq!(binomial(n, k), 0);
            }
        }

        /// Sum of row n is 2^n.
        #[test]
        fn prop_row_sums_to_power_of_two(n in 0u64..=67) {
            let mut sum: u128 = 0;
            for k in 0..=n {
                sum += binomial(n, k) as u128;
            }
            prop_assert_eq!(sum, 1u128 << n);
        }
    }
}
